 */

require_once __DIR__ . '/../Utils/MachineFingerprint.php';
require_once __DIR__ . '/LicenseService.php';

class SetupProgressService
{
    private const SECRET_FILE = __DIR__ . '/../../config/.setup_secret.tmp';
    private const TOKEN_TTL_SECONDS = 1800; // 30 minutes validity window for setup steps

    /**
     * Issues a cryptographic token certifying completion of a setup step.
     */
    public static function issueStepToken(int $step): string
    {
        $secret = self::getOrCreateSecret();
        $machineId = LicenseService::getMachineId(false);

        $payload = [
            'step'       => $step,
            'machine_id' => $machineId,
            'issued_at'  => time(),
            'expires_at' => time() + self::TOKEN_TTL_SECONDS,
            'nonce'      => bin2hex(random_bytes(16)),
        ];

        $json = json_encode($payload, JSON_UNESCAPED_SLASHES);
        $encoded = rtrim(strtr(base64_encode($json), '+/', '-_'), '=');
        $sig = hash_hmac('sha256', $encoded, $secret);

        return $encoded . '.' . $sig;
    }

    /**
     * Extracts setup progression token from request headers or active session.
     * Evaluates both and selects the token certifying the higher progression step.
     */
    public static function getRequestToken(): ?string
    {
        $headerToken = !empty($_SERVER['HTTP_X_SETUP_TOKEN']) ? trim((string)$_SERVER['HTTP_X_SETUP_TOKEN']) : null;
        $sessionToken = !empty($_SESSION['pos_setup_token']) ? trim((string)$_SESSION['pos_setup_token']) : null;

        if ($headerToken && $sessionToken) {
            $stepHeader = self::extractTokenStep($headerToken);
            $stepSession = self::extractTokenStep($sessionToken);
            return ($stepSession > $stepHeader) ? $sessionToken : $headerToken;
        }

        return $headerToken ?: $sessionToken;
    }

    public static function extractTokenStep(string $token): int
    {
        if (!str_contains($token, '.')) return 0;
        [$encoded] = explode('.', $token, 2);
        $json = base64_decode(strtr($encoded, '-_', '+/'), true);
        $payload = $json ? json_decode($json, true) : null;
        return (int)($payload['step'] ?? 0);
    }

    /**
     * Checks if target database is already physically configured and operational on disk.
     */
    public static function isDatabaseCertified(): bool
    {
        $configPath = __DIR__ . '/../../config/database.php';
        if (!is_file($configPath)) {
            return false;
        }
        try {
            require_once __DIR__ . '/../Database.php';
            $db = Database::getConnection();
            $stmt = $db->query("SHOW TABLES LIKE 'setup_state'");
            if ($stmt && $stmt->fetch()) {
                return true;
            }
            $stmt2 = $db->query("SHOW TABLES LIKE 'users'");
            return (bool)($stmt2 && $stmt2->fetch());
        } catch (\Throwable $e) {
            return false;
        }
    }

    /**
     * Verifies that the provided token certifies completion of the required prior step.
     *
     * @return array{valid: bool, step?: int, error?: string}
     */
    public static function verifyStepToken(?string $token, int $requiredMinStep): array
    {
        // 1. License on disk must also be physically valid
        $licStatus = LicenseService::checkLicenseStatus(false);
        if (!$licStatus['valid']) {
            return [
                'valid' => false,
                'error' => 'Step 1 License Verification is required: ' . ($licStatus['message'] ?? 'Invalid license.'),
            ];
        }

        if (empty($token) || !str_contains($token, '.')) {
            // Ground-truth fallback: If Step 2 is required and database is operational
            if ($requiredMinStep <= 2 && self::isDatabaseCertified()) {
                $freshToken = self::issueStepToken(2);
                $_SESSION['pos_setup_token'] = $freshToken;
                return [
                    'valid' => true,
                    'step'  => 2,
                ];
            }
            return [
                'valid' => false,
                'error' => "Setup token missing. You must complete Step {$requiredMinStep} first.",
            ];
        }

