​‌‌‌​‌​‌​‌‌​‌‌‌​​‌‌​​​​‌​‌‌‌​‌​‌​‌‌‌​‌​​​‌‌​‌​​​​‌‌​‌‌‌‌​‌‌‌​​‌​​‌‌​‌​​‌​‌‌‌‌​‌​​‌‌​​‌​‌​‌‌​​‌​​​​‌​​​​​​‌‌‌​‌‌​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌​​​‌‌​​​​‌​‌‌‌​‌​​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌‌​​​‌​​​​​​‌‌​​​​‌​‌‌​‌‌‌​​‌‌​​‌​​​​‌​​​​​​‌​​‌‌​‌​‌​‌​‌​‌​‌​‌​​‌‌​‌​‌​‌​​​​‌​​​​​​‌​​​​‌​​‌​​​‌​‌​​‌​​​​​​‌​‌​​‌​​‌​​​‌​‌​‌​​​‌‌​​‌​‌​‌​‌​‌​‌​​‌‌​‌​​​‌​‌​‌​​​‌​​​​‌​​​​​​‌​​‌​​‌​‌​​‌‌​‌​‌​​‌‌​‌​‌​​​‌​‌​‌​​​‌​​​‌​​‌​​‌​‌​​​​​‌​‌​‌​‌​​​‌​​​‌​‌​‌​​‌‌​​​‌​‌‌​​‌​​‌​‌‌‌​﻿‍ */

        [$encoded, $sig] = explode('.', $token, 2);
        $secret = self::getOrCreateSecret();
        $expectedSig = hash_hmac('sha256', $encoded, $secret);

        if (!hash_equals($expectedSig, $sig)) {
            if ($requiredMinStep <= 2 && self::isDatabaseCertified()) {
                $freshToken = self::issueStepToken(2);
                $_SESSION['pos_setup_token'] = $freshToken;
                return [
                    'valid' => true,
                    'step'  => 2,
                ];
            }
            return [
                'valid' => false,
                'error' => 'Invalid or forged setup state progression token.',
            ];
        }

        $decodedJson = base64_decode(strtr($encoded, '-_', '+/'), true);
        if ($decodedJson === false) {
            return [
                'valid' => false,
                'error' => 'Corrupted setup token encoding.',
            ];
        }

        $payload = json_decode($decodedJson, true);
        if (!is_array($payload) || !isset($payload['step'], $payload['machine_id'], $payload['expires_at'])) {
            return [
                'valid' => false,
                'error' => 'Malformed setup token payload.',
            ];
        }

        // Assert expiry
        if (time() > (int)$payload['expires_at']) {
            if ($requiredMinStep <= 2 && self::isDatabaseCertified()) {
                $freshToken = self::issueStepToken(2);
                $_SESSION['pos_setup_token'] = $freshToken;
                return [
                    'valid' => true,
                    'step'  => 2,
                ];
            }
            return [
                'valid' => false,
                'error' => 'Setup progression session has expired. Please restart the setup wizard.',
            ];
        }

        // Assert machine binding
        $currentMachineId = LicenseService::getMachineId(false);
        if (MachineFingerprint::normalizeMachineId((string)$payload['machine_id']) !== MachineFingerprint::normalizeMachineId($currentMachineId)) {
            return [
                'valid' => false,
                'error' => 'Setup token is bound to a different machine identifier.',
            ];
        }

        // Assert step monotonicity
        if ((int)$payload['step'] < $requiredMinStep) {
            // Ground-truth fallback: If Step 2 is required and database is operational
            if ($requiredMinStep <= 2 && self::isDatabaseCertified()) {
                $freshToken = self::issueStepToken(2);
                $_SESSION['pos_setup_token'] = $freshToken;
                return [
                    'valid' => true,
                    'step'  => 2,
                ];
            }
            return [
                'valid' => false,
                'error' => "Action forbidden. Step {$requiredMinStep} must be certified before proceeding.",
            ];
        }

        return [
            'valid' => true,
            'step'  => (int)$payload['step'],
        ];
    }

    /**
     * Purges setup ephemeral secret permanently upon completion of final setup step.
     */
    public static function destroy(): void
    {
        if (is_file(self::SECRET_FILE)) {
            @unlink(self::SECRET_FILE);
        }
    }

    private static function getOrCreateSecret(): string
    {
        if (is_file(self::SECRET_FILE)) {
            $secret = @file_get_contents(self::SECRET_FILE);
            if ($secret && strlen($secret) >= 32) {
                return $secret;
            }
        }

        $newSecret = bin2hex(random_bytes(32));
        $dir = dirname(self::SECRET_FILE);
        if (!is_dir($dir)) {
            @mkdir($dir, 0755, true);
        }
        @file_put_contents(self::SECRET_FILE, $newSecret, LOCK_EX);
        return $newSecret;
